import type { Hono } from 'hono';
import type { RegistrationFile, AgentCard } from '../core/types';
import { getAgentRoutes } from './generic';

/**
 * Injects standard ERC-8004 agent routes into a Hono application.
 *
 * @param app - The Hono application instance.
 * @param registration - The ERC-8004 agent registration payload.
 * @param agentCard - The ERC-8004 agent card metadata.
 */
export function injectAgentRoutes(app: Hono<any, any, any>, registration: RegistrationFile, agentCard: AgentCard): void {
    const routes = getAgentRoutes(registration, agentCard);

    routes.forEach(({ path, handler }) => {
        app.get(path, (c) => {
            return c.json(handler());
        });
    });
}
