import type { RegistrationFile, AgentCard } from '../core/types';

export const AGENT_JSON_ROUTE = '/.well-known/agent.json';
export const WELL_KNOWN_AGENT_CARD_ROUTE = '/.well-known/agent-card.json';
export const WELL_KNOWN_AGENT_REGISTRATION_ROUTE = '/.well-known/agent-registration.json';

export function getAgentRoutes(registration: RegistrationFile, agentCard: AgentCard): {
    path: string;
    handler: () => RegistrationFile | AgentCard;
}[] {
    return [
        { path: AGENT_JSON_ROUTE, handler: () => agentCard },
        { path: WELL_KNOWN_AGENT_CARD_ROUTE, handler: () => agentCard },
        { path: WELL_KNOWN_AGENT_REGISTRATION_ROUTE, handler: () => registration },
    ];
}
